import { useEffect, useState } from "react";
import { useTheme } from "../context/ThemeContext";

const roles = ["Web Developer", "Mobile Developer", "Systems Architect"];

export default function Hero() {
  const [roleIndex, setRoleIndex] = useState(0);
  const [displayed, setDisplayed] = useState("");
  const [typing, setTyping] = useState(true);
  const { theme } = useTheme();
  const isDark = theme === "dark";

  useEffect(() => {
    const target = roles[roleIndex];
    let i = displayed.length;
    if (typing) {
      if (i < target.length) {
        const t = setTimeout(() => setDisplayed(target.slice(0, i + 1)), 60);
        return () => clearTimeout(t);
      } else {
        const t = setTimeout(() => setTyping(false), 1800);
        return () => clearTimeout(t);
      }
    } else {
      if (i > 0) {
        const t = setTimeout(() => setDisplayed(target.slice(0, i - 1)), 35);
        return () => clearTimeout(t);
      } else {
        setRoleIndex((prev) => (prev + 1) % roles.length);
        setTyping(true);
      }
    }
  }, [displayed, typing, roleIndex]);

  return (
    <section
      id="hero"
      className={`relative min-h-screen flex flex-col justify-center pt-16 overflow-hidden transition-colors duration-300
        ${isDark ? "bg-ink-950" : "bg-paper-50"}`}
    >
      {/* Background grid */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `linear-gradient(${isDark ? "#c2c8cf" : "#9ba3ad"} 1px, transparent 1px), linear-gradient(90deg, ${isDark ? "#c2c8cf" : "#9ba3ad"} 1px, transparent 1px)`,
          backgroundSize: "60px 60px",
          opacity: isDark ? 0.035 : 0.06,
        }}
      />

      {/* Gradient orb */}
      <div
        className="absolute top-1/3 right-0 w-[500px] h-[500px] rounded-full blur-3xl pointer-events-none"
        style={{
          background: "radial-gradient(circle, #5a9e88, transparent 70%)",
          opacity: isDark ? 0.05 : 0.07,
        }}
      />

      <div className="relative max-w-6xl mx-auto px-6 py-24 w-full">

        {/* ── TWO-COLUMN LAYOUT: text left | photo right ─────────────────── */}
        <div className="grid lg:grid-cols-[1fr_auto] gap-12 lg:gap-20 items-center">

          {/* LEFT: content */}
          <div>
            {/* Available label */}
            <div className="flex items-center gap-3 mb-10">
              <span className="section-label">Available for Projects</span>
              <span className="w-2 h-2 rounded-full bg-accent-glow animate-pulse" />
            </div>

            {/* Headline */}
            <h1 className="font-display font-extrabold leading-[1.05] mb-6">
              <span className={`block text-4xl sm:text-6xl lg:text-7xl mb-2 transition-colors duration-300
                ${isDark ? "text-stone-200" : "text-gray-900"}`}>
                Building Systems
              </span>
              <span className={`block text-4xl sm:text-6xl lg:text-7xl mb-2 transition-colors duration-300
                ${isDark ? "text-stone-400" : "text-gray-500"}`}>
                That Work in
              </span>
              <span className="block text-4xl sm:text-6xl lg:text-7xl text-accent-glow">
                Production.
              </span>
            </h1>

            {/* Typewriter */}
            <div className="flex items-center gap-2 mb-8 h-8">
              <span className={`font-mono text-sm ${isDark ? "text-stone-500" : "text-gray-400"}`}>&gt;</span>
              <span className="font-mono text-accent-glow text-sm sm:text-base">{displayed}</span>
              <span className="font-mono text-accent-glow text-sm animate-blink">_</span>
            </div>

            {/* Subtext */}
            <p className={`max-w-xl text-base sm:text-lg leading-relaxed mb-12 transition-colors duration-300
              ${isDark ? "text-stone-400" : "text-gray-600"}`}>
              I build secure, structured web and mobile applications for businesses —
              PHP backends, normalized databases, Flutter apps with Firebase. Clean
              architecture. Maintainable code. Systems designed to last.
            </p>

            {/* CTAs */}
            <div className="flex flex-wrap gap-4 mb-16">
              <a href="#projects" className="btn-primary">
                View Projects
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M5 12h14M12 5l7 7-7 7"/>
                </svg>
              </a>
              <a href="#contact" className="btn-secondary">Get in Touch</a>
            </div>

            {/* Stats */}
            <div className={`flex flex-wrap gap-10 border-t pt-8 transition-colors duration-300
              ${isDark ? "border-wire" : "border-wire-light"}`}>
              {[
                { value: "4th Year", label: "IT Student" },
                { value: "PHP + SQL", label: "Web Stack" },
                { value: "Flutter",   label: "Mobile Stack" },
                { value: "Firebase",  label: "Cloud Backend" },
              ].map((stat) => (
                <div key={stat.label}>
                  <div className={`font-display font-bold text-lg ${isDark ? "text-stone-200" : "text-gray-900"}`}>
                    {stat.value}
                  </div>
                  <div className={`font-mono text-xs tracking-wider uppercase ${isDark ? "text-stone-500" : "text-gray-400"}`}>
                    {stat.label}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* RIGHT: profile photo ──────────────────────────────────────────
              To replace placeholder:
                1. Add your photo to /public/images/profile/
                2. Rename it to profile-photo.jpg (or update the src below)
              Recommended size: 400×400px or larger square crop
          ──────────────────────────────────────────────────────────────── */}
          <div className="hidden lg:flex justify-center">
            <div className="relative">
              {/* Decorative ring */}
              <div
                className="absolute -inset-3 rounded-full opacity-20"
                style={{ background: "conic-gradient(from 90deg, #5a9e88, transparent, #5a9e88)" }}
                aria-hidden="true"
              />
              {/* Outer border ring */}
              <div className={`absolute -inset-1 rounded-full border transition-colors duration-300
                ${isDark ? "border-wire" : "border-wire-light"}`}
                aria-hidden="true"
              />
              {/* Photo frame */}
              <div className={`relative w-64 h-64 xl:w-72 xl:h-72 rounded-full overflow-hidden border-2 shadow-2xl transition-colors duration-300
                ${isDark ? "border-ink-600" : "border-paper-300"}`}>
                {/* Replace this image with your professional photo */}
                <img
                  src="/images/profile/profile-photo.svg"
                  alt="Developer profile photo"
                  width="288"
                  height="288"
                  className="w-full h-full object-cover"
                  loading="eager"
                />
              </div>
              {/* Status badge */}
              <div className={`absolute bottom-4 right-0 flex items-center gap-2 px-3 py-1.5 rounded-full border text-xs font-mono shadow-lg transition-colors duration-300
                ${isDark
                  ? "bg-ink-800 border-wire text-stone-400"
                  : "bg-white border-wire-light text-gray-500"}`}>
                <span className="w-1.5 h-1.5 rounded-full bg-accent-glow animate-pulse" />
                Open to work
              </div>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
}
